-- Feelings: Word Scales — one unit per family of the wheel
update public.study_sets set units = (select jsonb_agg(u order by (u->>'u')::int) from (
    select u from jsonb_array_elements(units) u where (u->>'u')::int < 8
    union all select x from jsonb_array_elements('[{"u": 8, "name": "😨 Feelings wheel: Fear"}, {"u": 9, "name": "😠 Feelings wheel: Anger"}, {"u": 10, "name": "🤢 Feelings wheel: Disgust"}, {"u": 11, "name": "😢 Feelings wheel: Sad"}, {"u": 12, "name": "😊 Feelings wheel: Happy"}, {"u": 13, "name": "😲 Feelings wheel: Surprise"}]'::jsonb) x) y)
 where id = '00000000-0000-4000-8000-00000000fee1';
create temp table fam(u int, hw text, k int);
