-- words already in the set get the family as an extra unit
update public.set_entries e set also_units = (select array(select distinct x from unnest(coalesce(e.also_units, '{}') || array[f.u]) x where x <> e.unit order by x))
  from fam f, public.words w
 where e.set_id = '00000000-0000-4000-8000-00000000fee1' and w.id = e.word_id and lower(w.headword) = f.hw;
-- the others are added to the family unit
insert into public.set_entries (id, set_id, position, kind, unit, also_units, word_id)
select ('00000000-0000-4000-8000-' || lpad(to_hex(f.k), 8, '0') || 'fee1')::uuid, '00000000-0000-4000-8000-00000000fee1', f.k, 'term', f.u, '{}', w.id
from fam f join public.words w on w.lang = 'en' and lower(w.headword) = f.hw and w.sense = ''
where not exists (select 1 from public.set_entries e where e.set_id = '00000000-0000-4000-8000-00000000fee1' and e.word_id = w.id)
on conflict (id) do nothing;
drop table fam;

-- check
select (select count(*) from public.words where lang = 'en' and sense = '' and lower(headword) in ('disgust', 'surprise', 'insecure', 'submissive', 'rejected', 'humiliated', 'hurt', 'threatened', 'hateful', 'mad', 'aggressive', 'critical', 'disapproval', 'awful', 'avoidance', 'guilty', 'abandoned', 'bored', 'intimate', 'powerful', 'accepted', 'proud', 'interested', 'excited', 'amazed', 'confused', 'startled', 'overwhelmed', 'inadequate', 'inferior', 'worthless', 'insignificant', 'alienated', 'disrespected', 'ridiculed', 'embarrassed', 'jealous', 'resentful', 'violated', 'enraged', 'provoked', 'hostile', 'infuriated', 'withdrawn', 'suspicious', 'skeptical', 'sarcastic', 'judgmental', 'loathing', 'repugnant', 'revolted', 'revulsion', 'detestable', 'aversion', 'hesitant', 'remorseful', 'ashamed', 'ignored', 'victimized', 'powerless', 'vulnerable', 'empty', 'isolated', 'apathetic', 'open', 'playful', 'sensitive', 'loving', 'provocative', 'fulfilled', 'respected', 'inquisitive', 'amused', 'liberated', 'eager', 'awe', 'astonished', 'perplexed', 'disillusioned', 'dismayed', 'shocked')) as wheel_words_added,
